args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?mother ?motherLabel ?deathPlaceRes ?deathPlaceResLabel ?deathPlaceLit WHERE {
  dbr:Sibylla_of_Armenia dbp:mother ?mother .
  OPTIONAL { ?mother dbo:deathPlace ?deathPlaceRes . }
  OPTIONAL { ?mother dbp:deathPlace ?deathPlaceLit . }
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = 'en') }
  OPTIONAL { ?deathPlaceRes rdfs:label ?deathPlaceResLabel . FILTER(lang(?deathPlaceResLabel) = 'en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?mother ?deathPlaceRes ?deathPlaceLit WHERE {
  dbr:Sibylla_of_Armenia dbp:mother ?mother .
  OPTIONAL { ?mother dbo:deathPlace ?deathPlaceRes . }
  OPTIONAL { ?mother dbp:deathPlace ?deathPlaceLit . }
} LIMIT 10

